/// Every sound effect the game can play.
///
/// The WAV files under `assets/audio/` are generated by
/// `tool/generate_sounds.py` (pure synthesis, no third-party audio).
enum GameSound {
  /// One square of token movement.
  step('audio/step.wav', 0.45),

  /// The die is rolled.
  dice('audio/dice.wav', 0.8),

  /// The roll is a six.
  six('audio/six.wav', 0.7),

  /// A token leaves its base and enters the board.
  enter('audio/enter.wav', 0.7),

  /// A token captures an opponent token.
  capture('audio/capture.wav', 0.9),

  /// A token reaches home.
  home('audio/home.wav', 0.8),

  /// Third six in one turn: the whole turn is cancelled.
  cancelled('audio/cancelled.wav', 0.7),

  /// The match is over.
  win('audio/win.wav', 0.9),

  /// A captured token slides back to its base.
  tokenReturn('audio/return.wav', 0.75),

  /// One rank of the final result appears.
  reveal('audio/reveal.wav', 0.6);

  /// Path relative to `assets/` (the form `AssetSource` expects).
  final String asset;

  /// Playback volume, 0..1.
  final double volume;

  const GameSound(this.asset, this.volume);
}
